import{_ as o,o as d,c,a2 as a}from"./chunks/framework.BU31gs4v.js";const u=JSON.parse('{"title":"附录 D 练习参考答案","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/d-answers.md","filePath":"appendix/d-answers.md","lastUpdated":1791479463000}'),t={name:"appendix/d-answers.md"};function l(i,e,r,n,s,m){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="附录-d-练习参考答案" tabindex="-1">附录 D 练习参考答案 <a class="header-anchor" href="#附录-d-练习参考答案" aria-label="Permalink to &quot;附录 D 练习参考答案&quot;">​</a></h1><blockquote><p>“巩固”题多数是动手观察，这里给出应当看到的现象；“扩展”题给出实现要点；“读源码”题给出答案与依据。</p></blockquote><h2 id="第-1-章" tabindex="-1">第 1 章 <a class="header-anchor" href="#第-1-章" aria-label="Permalink to &quot;第 1 章&quot;">​</a></h2><ol><li>两个块（<code>persona</code>、<code>human</code>）；<code>&lt;memory_metadata&gt;</code> 里有 AGENT_ID、CONVERSATION_ID、编译时间、recall 中的消息数（每个回合至少 +2，带工具调用的回合 +4）。</li><li>在 <code>memory_replace</code> 里：<code>new_text === &quot;&quot;</code> 时用 <code>split(&quot;\\n&quot;).filter(l =&gt; !l.includes(old))</code> 删整行。新风险：agent 可以“遗忘”——误删、被提示注入诱导删除，而且 v0.1 没有历史可以恢复。这正是第 6 章引入 git 的动机之一。</li><li>技能通过 <code>&lt;available_skills&gt;</code> 列表进入系统提示（本地后端：<code>appendAvailableSkillsBlock()</code>，名字来自请求体的 <code>client_skills</code>），技能正文按需加载；其他按项目的上下文通过 <code>&lt;system-reminder&gt;</code> 注入。</li></ol><h2 id="第-2-章" tabindex="-1">第 2 章 <a class="header-anchor" href="#第-2-章" aria-label="Permalink to &quot;第 2 章&quot;">​</a></h2><ol><li>见第 2 章 2.1 节的 mini-letta 目录树；补上：<code>agent.json</code>（第 1 章，store 写，CLI/loop 读）、<code>memory/</code>（第 4 章）、<code>context.json</code>（第 12 章，压缩写、loop 读）、<code>system-prompt.json</code>（第 9 章）、<code>pending-reminders.json</code>（第 9 章，回合后写、回合前读）、<code>compaction-event.json</code>（第 12 章写、第 14 章读）、<code>reflection-state.json</code>（第 14 章）、<code>memory-worktrees/</code>、<code>reflections/payloads/</code>、<code>reflection.lock</code>（第 15–17 章）。</li><li>增加 <code>format</code> 参数：v1 时 <code>normalized.startsWith(&quot;system/&quot;)</code>。</li><li>子 agent 进程会继承父进程的 <code>MEMORY_DIR</code>/<code>AGENT_ID</code> 环境变量；如果它被派去处理另一个 agent（或父 agent 的 worktree），环境变量就是错的。运行时上下文是调用方显式设定的作用域，更可信。</li></ol><h2 id="第-3-章" tabindex="-1">第 3 章 <a class="header-anchor" href="#第-3-章" aria-label="Permalink to &quot;第 3 章&quot;">​</a></h2><ol><li>记忆变化走的是“系统提示不变 + 记录新 revision”的分支：<code>content</code> 保留旧值以保住提示缓存，<code>memfsRevision</code>、<code>coreMemory</code>、<code>compiledAt</code> 更新为新值，免得下一步重复生成 <code>&lt;memory_update&gt;</code>。</li><li>只能在<strong>后面</strong>追加：例如只发增量（变化了的文件），或在 <code>&lt;memory_update&gt;</code> 里声明“取代之前所有的 memory_update”。任何修改已有消息的方案都会破坏缓存前缀。</li><li>压缩重写了上下文的开头（把一段消息换成摘要），提示缓存的前缀已经失效；此时顺便替换系统提示不会再额外损失缓存。</li></ol><h2 id="lab-1" tabindex="-1">Lab 1 <a class="header-anchor" href="#lab-1" aria-label="Permalink to &quot;Lab 1&quot;">​</a></h2><ol><li>加一条规则：匹配 <code>^忘掉[:：](.+)$</code>，调用 <code>memory_replace({label:&quot;human&quot;, old_text:&quot;- X&quot;, new_text:&quot;&quot;})</code>；测试断言 <code>human</code> 块不再包含 X。</li><li>在循环里每次调用模型前 <code>onEvent?.({ type: &quot;step&quot;, n: step })</code>；CLI 打印 <code>· step n</code>。</li><li>每次 <code>execute()</code> 是一“步”：letta-code 的工具（客户端工具）在客户端执行，结果以新的请求发回后端，后端再执行一次。所以本地后端的 <code>resolveSystemPromptForTurn</code> 每一步都会被调用。</li></ol><h2 id="第-4-章" tabindex="-1">第 4 章 <a class="header-anchor" href="#第-4-章" aria-label="Permalink to &quot;第 4 章&quot;">​</a></h2><ol><li><code>name</code> 分别是 <code>Persona</code>、<code>Human</code>、<code>Project Conventions</code>（下划线和连字符都被当作分词符）。</li><li>检查 <code>relativePath</code> 不以 <code>/</code> 开头、没有 <code>.</code>/<code>..</code> 段；用 <code>toLocaleLowerCase(&quot;en-US&quot;)</code> 比较已有路径。</li><li>注释说：如果不在创建时原子地打标签、插入根块，Cloud 上的 agent 会“born without GIT_MEMORY_ENABLED_TAG”，此后所有基于标签的检查都会把它当成非 MemFS agent——“on every machine, forever”；原子地做，即使进程中途崩溃，服务器也已经为它初始化了 v2 仓库，后续的惰性同步能把剩下的步骤补齐。</li></ol><h2 id="第-5-章" tabindex="-1">第 5 章 <a class="header-anchor" href="#第-5-章" aria-label="Permalink to &quot;第 5 章&quot;">​</a></h2><ol><li>删除 <code>projects/archive/MEMORY.md</code> 后再提交会被拒：<code>projects/archive/old.md: missing required index projects/archive/MEMORY.md</code>。</li><li>深度 3（<code>a/b/c/d.md</code> 有 3 个目录段），超过 <code>maxDepth: 2</code> 被拒：<code>depth 3 exceeds maxDepth 2</code>；另外 <code>projects/archive/2025/MEMORY.md</code> 也必须存在。</li><li>通过上级索引里的普通 Markdown 链接被发现（“references as synapses”）。这是有意的：系统提示只放第一层目录，更深的结构交给索引链，保持常驻部分的大小与目录深度无关。</li></ol><h2 id="第-6-章" tabindex="-1">第 6 章 <a class="header-anchor" href="#第-6-章" aria-label="Permalink to &quot;第 6 章&quot;">​</a></h2><ol><li><code>prompt --fresh</code> 的输出不含改坏的内容；<code>git stash</code> 后工作区恢复。</li><li>在 <code>commitMemoryPaths</code> 里 <code>try { git commit } catch { git restore --staged -- &lt;paths&gt;; throw }</code>；测试：写一个缺 frontmatter 的文件，调用后断言抛错且 <code>git diff --cached --name-only</code> 为空。</li><li>不带路径的 <code>git commit</code> 会把暂存区里<strong>所有</strong>东西一起提交，包括 agent 暂存的文件；<code>git commit -- &lt;paths&gt;</code> 只提交这些路径。letta-code 的 harness 写者都在 <code>claimMemoryOperation</code> 锁内运行，并依赖提示词要求 agent 自己“stage 并在同一条命令里 commit”，从而缩小两者交错的窗口；但主 agent 不走这把锁，所以窗口并非为零。</li></ol><h2 id="第-7-章" tabindex="-1">第 7 章 <a class="header-anchor" href="#第-7-章" aria-label="Permalink to &quot;第 7 章&quot;">​</a></h2><ol><li>提交配置需要 <code>MINI_LETTA_CONSTRAINTS_UPDATE=1</code>；之后 mock 的“设定：”命令会失败，工具结果里是 <code>persona.md: read-only file cannot be created, changed or removed</code>，mock 回复“操作失败：…”。</li><li>审计通过时记录 <code>last-valid-revision</code>；编译时如果 HEAD 审计失败，改为 <code>git show &lt;last-valid&gt;:&lt;path&gt;</code>。这并不违背“只认已提交的”——它变成了“只认已提交且有效的”，代价是 HEAD 与生效版本可能不一致，需要在提醒里明说。</li><li>技能是一个目录：除了 <code>SKILL.md</code> 还有 <code>scripts/</code>、<code>references/</code>、<code>templates/</code>；目录也让技能能被整体移动、删除、弃用，并让 <code>skills/</code> 下不会混进普通记忆文件。</li></ol><h2 id="lab-2" tabindex="-1">Lab 2 <a class="header-anchor" href="#lab-2" aria-label="Permalink to &quot;Lab 2&quot;">​</a></h2><ol><li><code>memory show &lt;path&gt;</code> → <code>git show HEAD:&lt;path&gt;</code>。</li><li>validator 里遍历暂存树，用 <code>git cat-file -s :&lt;path&gt;</code> 取大小，超过 1 MB 报错。</li><li><code>.git/hooks</code> 不会被 clone；CLI 升级后 hook 脚本（以及嵌入的校验函数源码）可能变了，所以在 clone、pull、init 时都重新安装，保证 hook 与当前 CLI 一致。</li></ol><h2 id="第-8-章" tabindex="-1">第 8 章 <a class="header-anchor" href="#第-8-章" aria-label="Permalink to &quot;第 8 章&quot;">​</a></h2><ol><li>会：<code>projects/</code> 出现在 <code>&lt;deferred-memory&gt;</code>；<code>projects/sub/</code> 不会（只列第一层），要靠 <code>projects/MEMORY.md</code> 里的链接发现。</li><li>写一个 <code>escapeXmlAttribute</code>（<code>&amp; &quot; &#39; &lt; &gt;</code> 五个字符），用于 <code>path</code>、<code>index</code> 属性。</li><li>hook 不检查文件名是否是合法的 XML 名称，所以 <code>&lt;my notes&gt;</code> 可以出现。模型并不需要严格合法的 XML——这些标签只是给模型看的分节符号——但它会让任何试图用 XML 解析器处理系统提示的工具出错，也让标签边界变得含糊。</li></ol><h2 id="第-9-章" tabindex="-1">第 9 章 <a class="header-anchor" href="#第-9-章" aria-label="Permalink to &quot;第 9 章&quot;">​</a></h2><ol><li>三条 <code>&lt;memory_update&gt;</code>；<code>recompile</code> 删除缓存，下一步完整编译，新系统提示含最新记忆，不再产生新的 <code>&lt;memory_update&gt;</code>（但旧的三条仍在对话历史里，直到压缩）。</li><li>记录上一次 <code>&lt;memory_update&gt;</code> 对应的 revision，用 <code>git diff --name-only &lt;old&gt; &lt;new&gt;</code> 找出变化的 core 文件，只渲染它们；模型需要拼接多个增量，提示文案里要说明“只包含变化的文件”。</li><li>最小改动是让 <code>&lt;memory_update&gt;</code> 进入对话存储（例如在 <code>getOrCompileSystemPrompt</code> 返回后由后端追加一条持久化消息），这样 <code>uiMessages</code> 里就有它；改 pi-stream-adapter 只影响单次请求；改 <code>persistExecutorStream</code> 需要区分“模型产生的消息”和“harness 注入的消息”。无论哪种，都要遵守 CLAUDE.md 的“user 角色 + system-reminder”规则。</li></ol><h2 id="第-10-章" tabindex="-1">第 10 章 <a class="header-anchor" href="#第-10-章" aria-label="Permalink to &quot;第 10 章&quot;">​</a></h2><ol><li>例：“inspect Git status and read the current files before editing”→ 无强制；“stage only the files you changed”→ 无强制（mini 的 mock 遵守）；“commit in the same shell call”→ 无强制；“Verify the committed changes”→ 回合后 <code>MEMORY COMMIT NEEDED</code> 提醒是事后反馈。</li><li>解析每个 <code>MEMORY.md</code> 里的 <code>](相对路径)</code>，检查目标存在。放在提醒里更合适：断链不会让记忆“错误”，只会降低可发现性，而 hook 拒绝会挡住所有提交（第 5 章的整树副作用）。</li><li>例如本地提示词没有说明根 <code>MEMORY.md</code> 不能有 frontmatter、其他文件“恰好 <code>name</code> + <code>description</code>”、子目录需要索引——而 hook 按这些规则拒绝提交，本地 agent 只能从报错中学。</li></ol><h2 id="lab-3" tabindex="-1">Lab 3 <a class="header-anchor" href="#lab-3" aria-label="Permalink to &quot;Lab 3&quot;">​</a></h2><ol><li>修改 <code>agent.system</code> 后调用 <code>resolveSystemPrompt</code>：返回的 <code>systemPrompt</code> 含新文本，<code>memoryUpdate</code> 为 <code>undefined</code>。</li><li>在 <code>runTurn</code> 开始处把 <code>reminders</code> 通过 <code>onEvent({type:&quot;reminders&quot;, items})</code> 发出，CLI 打印。</li><li>当本地后端启用、或该 agent 启用了 MemFS 时才显示记忆目录（<code>isLocalBackendEnvEnabled() || settingsManager.isMemfsEnabled(id)</code>）——非 MemFS 的 agent 没有记忆目录可言。</li></ol><h2 id="第-11-章" tabindex="-1">第 11 章 <a class="header-anchor" href="#第-11-章" aria-label="Permalink to &quot;第 11 章&quot;">​</a></h2><ol><li>8 192 → 6 554（预留 1 638）；128 000 → 111 616；1 000 000 → 983 616。</li><li><code>complete()</code> 返回 <code>usage</code>，存进 assistant 消息；估算时取最近一条带 usage 的 assistant 消息的值 + 其后消息的估算；压缩时给摘要消息打上时间戳，早于它的 usage 一律忽略。</li><li>用户故意设置小 <code>max_tokens</code> 时，以 <code>length</code> 停止是正常的产品行为，不该触发压缩；如果按 <code>max_tokens</code> 算阈值，一个很大的 <code>max_tokens</code> 会让 harness 过早压缩，一个很小的又会在上下文真的满了时不压缩。</li></ol><h2 id="第-12-章" tabindex="-1">第 12 章 <a class="header-anchor" href="#第-12-章" aria-label="Permalink to &quot;第 12 章&quot;">​</a></h2><ol><li><code>context.json</code> 里少了被摘要的那些 id，多了一条摘要消息的 id；<code>messages.jsonl</code> 只多不少；摘要消息的 <code>kind</code> 是 <code>&quot;summary&quot;</code>。</li><li>把 <code>estimateMessagesTokens(messages.slice(cutoff)) + floor</code> 与 <code>(1 - percentage) * window</code> 比较；压缩次数减少、每次保留的消息变少，锯齿变缓。</li><li><code>all</code> 模式下没有“保留最近消息原文”的需要，唯一不能被摘要掉的是还在等结果的工具调用——它的结果马上要追加在后面，调用必须原样在场。</li></ol><h2 id="第-13-章" tabindex="-1">第 13 章 <a class="header-anchor" href="#第-13-章" aria-label="Permalink to &quot;第 13 章&quot;">​</a></h2><ol><li>两个对话都会命中；分数不同来自 BM25 的长度归一化（短消息分数更高）和词频。</li><li>解析引号为短语，候选必须 <code>includes(phrase)</code>（CJK 不加空格边界、拉丁文加），命中短语加分。</li><li>好处：子 agent 知道父 agent 在做什么，能判断哪些检索结果相关；代价：每次 recall 都要带上父对话的全部上下文 token。<code>memory</code> 子 agent 拿到的是“自包含的指令”（描述里要求 “Make the assignment self-contained”），它需要的是记忆文件而不是父对话，所以不分叉，更便宜。</li></ol><h2 id="lab-4" tabindex="-1">Lab 4 <a class="header-anchor" href="#lab-4" aria-label="Permalink to &quot;Lab 4&quot;">​</a></h2><ol><li>900 的窗口阈值 720，地板（系统提示 + 工具 + agent-info）约 600，主对话几乎每回合都压缩，但仍能继续。我们实际跑了一下，真正出问题的是<strong>反思</strong>：CLI 让反思子 agent 共用这个 900 的窗口，于是每一次都是 <code>failed</code>（第 15 章踩坑记录 3 的同一个循环）。为此 mini-letta 加了 <code>MINI_LETTA_REFLECTION_CONTEXT_WINDOW</code>；设为 8000 后同样的场景反思 <code>merged</code>。</li><li>在 <code>COMPACTION_EVENT</code> 里记录被摘要消息的首尾 id；<code>recall_search</code> 读取 <code>context.json</code>，不在上下文中的命中标注 <code>(evicted)</code>。</li><li>那个判断是在问“滑动窗口这次压缩是否把上下文压到了窗口以内”，如果还超过整个窗口，下一次请求必然失败，就退回 <code>all</code>；而“超过阈值但没超过窗口”可以由下一次请求前的正常检查处理。</li></ol><h2 id="第-14-章" tabindex="-1">第 14 章 <a class="header-anchor" href="#第-14-章" aria-label="Permalink to &quot;第 14 章&quot;">​</a></h2><ol><li><code>stepsSinceLastReflection</code> 每次回合 +1（或 +2，带工具调用时），到 2 时触发；删掉 <code>reflectedThroughMessageId</code> 后，下一次反思会从头再看整个对话——重复内容由反思者的“已经记过了吗”过滤掉。</li><li>清单 JSON：<code>{ type: &quot;multi_transcript_reflection_payload&quot;, transcripts: [{ conversation_id, mode, payload_path, end_message_id }] }</code>；收尾时只对 <code>mode === &quot;unreflected&quot;</code> 的切片调用 <code>markReflected</code>。</li><li>Cloud 后端的消息在服务器上，客户端每次去拉代价大；客户端 transcript 是本机上已经看到的东西，可以离线、快速、按行切片；<code>source_message_id</code> 可能是合成的，说明它是客户端视角的记录，后端未必有一一对应的 id。</li></ol><h2 id="第-15-章" tabindex="-1">第 15 章 <a class="header-anchor" href="#第-15-章" aria-label="Permalink to &quot;第 15 章&quot;">​</a></h2><ol><li>mock 规则：匹配“别再叫我 X 了，叫我 Y”，生成 <code>sed -i &#39;s/X/Y/&#39; human.md</code>（或 Edit 工具）而不是追加。</li><li>一个模块级 <code>Map&lt;agentId, { delayMs, retryAt }&gt;</code>；<code>parent_dirty</code>/<code>merge_conflict</code> 时 <code>delayMs = min(prev*2 || 60_000, 30*60_000)</code>；<code>launchReflection</code> 开头检查 <code>retryAt</code>，<code>manual</code> 触发跳过检查；成功时删除记录。</li><li><code>explicit</code> 模式让主 agent 在一个“集成对话”里审阅反思分支再自己合并——适用于用户希望 agent 对后台改动“知情并认可”的场景，或需要按 <code>mergeInstructions</code> 有选择地合并。<code>requireAlreadyMerged</code> 检查反思分支是否确实已经是 HEAD 的祖先：防止集成对话声称合并了、其实没有。</li></ol><h2 id="第-16-章" tabindex="-1">第 16 章 <a class="header-anchor" href="#第-16-章" aria-label="Permalink to &quot;第 16 章&quot;">​</a></h2><ol><li>返回 <code>{ launched: false, reason: &quot;parent_dirty&quot; }</code>。开始时检查是为了不浪费一次反思；收尾时再查，是因为反思可能跑了几分钟，期间主仓库可能变脏。</li><li>memory worker 是主 agent 主动委派的、针对一个具体请求的改动，合并失败时保留分支让人或模型稍后处理比丢掉更好；反思是周期性的、可以从同一段 transcript 重来的，失败就清理重试最简单。主仓库脏不阻止 worker 合并，因为 git 只在改动重叠时才拒绝，那会表现为冲突。</li><li><code>branch -d</code> 只删除已合并的分支——在成功路径上，如果分支意外没有被合并，<code>-d</code> 会失败而不是丢失提交；失败路径本来就决定丢弃，才用 <code>-D</code>。</li></ol><h2 id="第-17-章" tabindex="-1">第 17 章 <a class="header-anchor" href="#第-17-章" aria-label="Permalink to &quot;第 17 章&quot;">​</a></h2><ol><li>第二个得到 <code>already_active</code>；<code>kill -9</code> 之后，锁文件里的 pid 已不存在，下一次 <code>tryAcquireLock</code> 回收并成功获取。</li><li>要点：worktree 标签用 <code>memory-worker</code>；合并用 <code>git merge</code>，主仓库脏不预先拒绝；冲突时 <code>merge --abort</code> 但<strong>不删除</strong>分支，返回分支名供后续处理；合并后同步、使系统提示失效。</li><li>要点：在主检出上运行；提示词照搬 <code>memory.md</code> 的 Git 一节（读两边、保留意图、不 abort/reset/stash、不清楚就保留现场并报告）；用一个记录文件防止对同一冲突重复启动修复。</li></ol><h2 id="lab-5" tabindex="-1">Lab 5 <a class="header-anchor" href="#lab-5" aria-label="Permalink to &quot;Lab 5&quot;">​</a></h2><ol><li>在 <code>resolveSystemPrompt</code> 写缓存时已经写进了反思者的对话目录（<code>agents/&lt;id&gt;~reflection/conversations/reflection-&lt;id&gt;/system-prompt.json</code>），用 <code>jq -r .content</code> 查看，可以看到父 agent 的 <code>&lt;human&gt;</code>、<code>&lt;persona&gt;</code>。</li><li>mock 读取任务提示里的 “Additional user-provided reflection instruction”，按关键词过滤候选事实。</li><li>崩溃隔离：子进程崩溃不影响主进程，mini 的同进程实现会一起崩；沙箱：letta-code 可以把整个子进程放进沙箱，mini 只能沙箱化 shell 命令、文件工具只靠守卫；<code>-p</code> 一次性模式：mini 必须等反思结束才能退出（否则进程退出反思被杀），letta-code 的后台子进程有自己的生命周期管理。</li></ol><h2 id="第-18-章" tabindex="-1">第 18 章 <a class="header-anchor" href="#第-18-章" aria-label="Permalink to &quot;第 18 章&quot;">​</a></h2><ol><li>冲突提醒里给出了 <code>git pull --rebase origin main</code> → 编辑冲突文件 → <code>git add</code> → <code>GIT_EDITOR=true git rebase --continue</code>。</li><li>post-commit hook：读 <code>git config --local mini-letta.memoryRepository.url</code>；<code>[ &quot;$branch&quot; = main ] || exit 0</code>；后台 <code>git push &quot;$url&quot; main:main &gt;&gt; .git/mirror.log 2&gt;&amp;1 &amp;</code>。</li><li>rebase 把别人的提交和自己的提交重新组合成一棵新树，这棵树可能违反约束（比如两边各加了一些内容，合起来超过了核心记忆预算）；推送前要校验的是“将要推上去的那棵树”。</li></ol><h2 id="第-19-章" tabindex="-1">第 19 章 <a class="header-anchor" href="#第-19-章" aria-label="Permalink to &quot;第 19 章&quot;">​</a></h2><ol><li>只看到 <code>agent-&lt;自己&gt;</code>，其他 agent 的目录不存在（tmpfs 覆盖）。</li><li>validator 里对每个暂存文件做正则匹配；误报可以用一个“需要人类批准”的环境变量放行，或者维护一个允许列表（比如 <code>.memfs.config.json</code> 里的 <code>secretScanAllow</code> glob，它本身受保护）。</li><li>letta-code 把记忆子 agent 自己的 agent <strong>目录</strong>（cwd 的直接父目录）挖回为可读，保证进程初始化能沿路径走到 cwd、环境变量得以保留。跨 agent 配置拒绝读取整个 agents 树，如果 cwd 在树里，就会触发这个空环境的坑，所以要求调用方保证 cwd 在树外（主 agent 的 cwd 通常是项目仓库）。</li></ol><h2 id="第-20-章" tabindex="-1">第 20 章 <a class="header-anchor" href="#第-20-章" aria-label="Permalink to &quot;第 20 章&quot;">​</a></h2><ol><li>在 <code>conversations()</code> 里读取 <code>compaction-event.json</code> 的 <code>at</code> 字段并在页面上显示。</li><li><code>doctor</code> 命令依次调用：<code>git status --porcelain</code>、<code>auditCommittedMemory</code>、<code>memoryTree</code> 里超过 <code>maxFileCharacters * 0.8</code> 的文件、解析 <code>MEMORY.md</code> 链接、<code>conversations()</code> 里 <code>stepsSinceReflection &gt; 50</code> 的对话。</li><li>以 SKILL.md 原文为准；一般包括：收集症状、查看当前记忆与系统提示、找出缺失或矛盾、判断是记忆问题还是 harness 问题、做最小修复并验证。Palace 能直接提供“当前记忆”“历史”“对话正在用的系统提示”“压缩与反思状态”这几类证据。</li></ol><h2 id="lab-6" tabindex="-1">Lab 6 <a class="header-anchor" href="#lab-6" aria-label="Permalink to &quot;Lab 6&quot;">​</a></h2><ol><li>新服务挂另一个 <code>data2</code> 卷和同一个 <code>remote</code> 卷，<code>command: [&quot;bun&quot;,&quot;src/cli.ts&quot;,&quot;chat&quot;,&quot;-a&quot;,&quot;agent-demo&quot;,&quot;-p&quot;,&quot;你知道我什么？&quot;]</code>；它会从 <code>remote</code> 克隆 <code>agent-demo</code> 的记忆——前提是 seed 运行时设置了 <code>MINI_LETTA_REMOTE_ROOT</code>（compose 里已设置）。</li><li>至少需要允许 <code>unshare</code>（用户命名空间）和挂载相关的系统调用；放宽容器的 seccomp/能力会削弱容器本身的隔离。多租户场景更常见的做法是每个 agent 一个容器，或在宿主机上用 bwrap，而不是“容器里再套 bwrap”。</li><li>静态文件：生成时刻的快照、没有监听端口、打开即用；服务器：数据实时、可部署共享，但多了一个需要保护的网络服务（mini 的 Palace 默认只监听 127.0.0.1、只读、校验 sha 参数）。</li></ol>',54)])])}const g=o(t,[["render",l]]);export{u as __pageData,g as default};
